use vstd::prelude::*;

verus! {

spec fn intersperse_spec(s: Seq<i32>, delim: i32) -> Seq<i32> {
    if s.len() == 0 {
        Seq::<i32>::empty()
    } else {
        Seq::<i32>::new(2 * s.len() - 1, |k: int|
            if k % 2 == 0 { s[k / 2] } else { delim }
        )
    }
}

fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        res@ == intersperse_spec(numbers@, delim),
{
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }

    // Result length is 2n - 1
    let mut res = Vec::with_capacity(2 * n - 1);

    for (i, &x) in numbers.iter().enumerate()
        invariant
            0 <= i <= n,
            res@ == intersperse_spec(numbers@.subrange(0, i as int), delim),
        decreases n - i,
    {
        if i > 0 {
            res.push(delim);
        }
        res.push(x);

        // Help the verifier connect the pushed elements to the spec
        assert(numbers@.subrange(0, (i + 1) as int).len() == (i + 1) as int);
        assert(res@ == intersperse_spec(numbers@.subrange(0, (i + 1) as int), delim));
    }

    res
}

} // verus!

